    if (this.FreeSpinsPurchaseData != null) cloned.FreeSpinsPurchaseData = this.FreeSpinsPurchaseData.Clone();
    if (this.RandomMysterySymbolId != null) cloned.RandomMysterySymbolId = this.RandomMysterySymbolId.slice();
