function LayoutManager() {
    XTLink.call(this);
    this.curWidth = -1;
    this.curHeight = -1;
    this.curMode = LayoutManager.Mode.Invalid;
    this.isInit = false;
    this.LandscapeWideRatio = 1.57;
    this.LandscapeWideFullRatio = 1.77;
    this.PortraitIPhoneRatio = .59;
    this.PortraitIPadRatio = .74;
    this.isMobile = true;
    this.isMini = false
}
LayoutManager.Mode = {
    Invalid: 0,
    Landscape: 1,
    Portrait: 2,
    LandscapeWide: 3,
    PortraitIPhone: 4,
    PortraitIPad: 5,
    LandscapeWideFull: 6
};
