    this.notificationsCameraDepth = 0;
    this.mustOpen = false;
    this.isRoundOpen = false;
    this.isNotificationOpen = false;
    this.cachedCamera = null;
    this.style = null;
    this.posC = null;
    this.posTL = null;
    this.posBR = null;
    this.replayRoot = null;
