        null;
    this.orderedJPText = ["MINI JACKPOT", "MINOR JACKPOT", "MAJOR JACKPOT", "GRAND JACKPOT"];
    this.singleJPText = "JACKPOT";
    this.curWinDesc = [];
    this.settings = null;
    this.receivedWinLines = null;
    this.isBonusWon = false;
    this.isFSWon = false;
    this.isCentered = false;
