goog.provide("UHT.BonusRespinLink_Chilliheat");
BonusRespinLink_Chilliheat.prototype = Object.create(BonusRespinLink_base.prototype);
BonusRespinLink_Chilliheat.prototype.constructor = BonusRespinLink_Chilliheat;

function BonusRespinLink_Chilliheat() {
    BonusRespinLink_base.call(this);
    this.reelStart = null;
    this.reelStopsWithWin = null;
    this.respinCounterFX = null;
    this.showLevel = null;
    this.levelSteps = null;
    this.moneySymbolId = 11;
    this.changeSymbolsLayer = null;
    this.currentLevel = -1
}
BonusRespinLink_Chilliheat.prototype.OnReelsStarts = function(reelsIdx) {
    this.reelStart.Start()
};
BonusRespinLink_Chilliheat.prototype.OnReelsStops = function(reelsIdx) {
    if (this.ReelStoppedWithNewSymbol(reelsIdx[0])) this.reelStopsWithWin.Start()
};
BonusRespinLink_Chilliheat.prototype.PutSymbolsOnNormalReels = function(symbols) {
    XT.SetObject(Vars.FirstScreenSymbols, symbols);
    this.normalReelsManager.InitFirstScreenSymbols();
    this.changeSymbolsLayer.symbolPositions = [];
    for (var i = 0; i < this.normalReelsManager.reels.length; i++)
        for (var j = 0; j < this.normalReelsManager.reels[i].symbolHolders.length; j++) {
            this.normalReelsManager.reels[i].symbolHolders[j].currentSymbol.SetNormal();
            var chilliReel = this.specialReelsManager.reels[i];
            chilliReel.customSymbolID = this.blankSymbolID;
            if (this.normalReelsManager.reels[i].symbolHolders[j].currentSymbol.symbolId != this.moneySymbolId) {
                this.changeSymbolsLayer.symbolPositions.push(j * this.normalReelsManager.reels.length + i);
                chilliReel.forceCustomSymbol[j] = false
            } else chilliReel.forceCustomSymbol[j] = true
        }
    this.changeSymbolsLayer.StartCustomCAT()
};
BonusRespinLink_Chilliheat.prototype.GetComputedScreenSymbols = function() {
    var resultScreenSymbols = XT.GetObject(Vars.ResultScreenSymbols);
    var computedScreenSymbols = [];
    for (var i = 0; i < resultScreenSymbols.length; i++) {
        computedScreenSymbols.push([]);
        for (var j = 0; j < resultScreenSymbols[i].length; j++) {
            var computedID = resultScreenSymbols[i][j];
            computedScreenSymbols[i].push(computedID)
        }
    }
    return computedScreenSymbols
};
BonusRespinLink_Chilliheat.prototype.InitRespinRound = function() {
    this.GenerateFakeReelSymbols();
    this.specialReelsManager.InitFirstScreenSymbols(this.GetBlankScreenSymbols());
    this.specialReelsManager.SetAllSymbolsToNormal();
    this.PutSymbolsOnNormalReels(XT.GetObject(Vars.ResultScreenSymbols));
    this.currentLevel = -1;
    this.StartNewRespin()
};
BonusRespinLink_Chilliheat.prototype.StartNewRespin = function() {
    this.ComputeCurrentLevel();
    if (this.bonusData.currentBonusRespin == this.bonusData.maxBonusRespins || this.bonusData.GameOver) {
        this.PutSymbolsOnNormalReels(XT.GetObject(Vars.ResultScreenSymbols));
        this.specialReelsManager.InitFirstScreenSymbols(this.GetBlankScreenSymbols());
        this.gameOver.Start()
    } else this.newRespin.Start()
};
BonusRespinLink_Chilliheat.prototype.ReelStoppedWithNewSymbol = function(reelIdx) {
    for (var j = 0; j < this.normalReelsManager.reels[reelIdx].symbolHolders.length; j++)
        if (this.normalReelsManager.reels[reelIdx].symbolHolders[j].currentSymbol.symbolId != this.GetReversedScreenSymbols()[reelIdx][j]) return true;
    return false
};
BonusRespinLink_Chilliheat.prototype.SetRespinsLeftValue = function(respinsLeft) {
    this.respinsLeftIndicator.text = respinsLeft
};
BonusRespinLink_Chilliheat.prototype.UpdateRespinsLeftValue = function() {
    this.respinsLeftIndicator.text = (this.bonusData.maxBonusRespins - this.bonusData.currentBonusRespin).toString();
    if (this.bonusData.currentBonusRespin == 0 || this.bonusData.ExtraRespinsWon > 0) this.respinCounterFX.Start()
};
BonusRespinLink_Chilliheat.prototype.IncreaseRespinsLeftBy = function(increseVal) {
    var currentlyDisplayed = _number.otoi(this.respinsLeftIndicator.text);
    var increase = _number.otoi(increseVal);
    this.respinsLeftIndicator.text = (currentlyDisplayed + increase).toString();
    if (increase > 0) this.respinCounterFX.Start()
};
BonusRespinLink_Chilliheat.prototype.ComputeCurrentLevel = function() {
    var screenSymbols = XT.GetObject(Vars.ResultScreenSymbols);
    var moneySymbols = 0;
    var i;
    for (i = 0; i < screenSymbols.length; i++)
        for (var j = 0; j < screenSymbols[i].length; j++)
            if (screenSymbols[i][j] == this.moneySymbolId) moneySymbols++;
    for (i = this.levelSteps.length - 1; i >= 0; i--)
        if (moneySymbols >= this.levelSteps[i] && this.currentLevel < i) {
            this.currentLevel = i;
            this.showLevel[this.currentLevel].Start();
            break
        }
};
BonusRespinLink_Chilliheat.prototype.Update = function() {
    if (this.shouldStopSpinning && this.resultReceived) {
        this.shouldStopSpinning = false;
        var stopPositions = [];
        var stopSymbols = this.GetReversedScreenSymbols();
        for (var i = 0; i < stopSymbols.length; i++) {
            for (var j = 0; j < stopSymbols[i].length; j++)
                if (this.normalReelsManager.reels[i].symbolHolders[j].currentSymbol.symbolId == this.moneySymbolId) stopSymbols[i][j] = this.blankSymbolID;
            stopSymbols[i] = stopSymbols[i].concat(this.fakeReelSymbols[i]);
            stopPositions.push(0)
        }
        this.specialReelsManager.OnReelSymbols(stopSymbols);
        this.specialReelsManager.OnSpinResultReceived(stopPositions)
    }
};
