goog.require("UHT.XTLink");
TextIntVariableReplace.prototype = Object.create(XTLink.prototype);
TextIntVariableReplace.prototype.constructor = TextIntVariableReplace;

function TextIntVariableReplace() {
    XTLink.call(this);
    this.replaceSource = "";
    this.replaceWith = null
}
TextIntVariableReplace.prototype.XTRegisterCallbacks = function() {
    XT.RegisterCallbackEvent(Vars.Evt_Internal_GUIInit, this.OnGUIInit, this)
};
TextIntVariableReplace.prototype.OnDestroy = function() {
    XT.UnregisterCallbackEvent(this.OnGUIInit, this)
};
TextIntVariableReplace.prototype.OnGUIInit = function() {
    var myLabel = this.GetComponent(UILabel);
    if (myLabel == null) return;
    if (this.replaceSource != "") {
        var iReplaceWith = XT.GetInt(this.replaceWith.name);
        if (iReplaceWith != 0) {
            this.replaceSource = this.replaceSource.replace(/[^0-9]/g, "");
            var strTextNoSpace = this.replaceSource;
            var strTextComma = strTextNoSpace.replace(/\d{1,3}(?=(\d{3})+(?!\d))/g, "$&,");
            var strTextPoint = strTextNoSpace.replace(/\d{1,3}(?=(\d{3})+(?!\d))/g, "$&.");
            var strTextSpace = strTextNoSpace.replace(/\d{1,3}(?=(\d{3})+(?!\d))/g,
                "$& ");
            if (myLabel.text.indexOf(strTextNoSpace) != -1) myLabel.text = myLabel.text.replace(strTextNoSpace, iReplaceWith.toString());
            else if (myLabel.text.indexOf(strTextComma) != -1) {
                var strReplaceComma = iReplaceWith.toString().replace(/\d{1,3}(?=(\d{3})+(?!\d))/g, "$&,");
                myLabel.text = myLabel.text.replace(strTextComma, strReplaceComma)
            } else if (myLabel.text.indexOf(strTextPoint) != -1) {
                var strReplacePoint = iReplaceWith.toString().replace(/\d{1,3}(?=(\d{3})+(?!\d))/g, "$&.");
                myLabel.text = myLabel.text.replace(strTextPoint,
                    strReplacePoint)
            } else if (myLabel.text.indexOf(strTextSpace) != -1) {
                var strReplaceSpace = iReplaceWith.toString().replace(/\d{1,3}(?=(\d{3})+(?!\d))/g, "$& ");
                myLabel.text = myLabel.text.replace(strTextSpace, strReplaceSpace)
            }
        }
    }
};
goog.require("UHT.Engine");
JackpotDisplayer_AGD.prototype = Object.create(FOXLink.prototype);
JackpotDisplayer_AGD.prototype.constructor = JackpotDisplayer_AGD;

function JackpotDisplayer_AGD() {
    FOXLink.call(this);
    this.orderedJackpots = null;
    this.orderedJackpotMasks = null;
    this.jackpotWinAmounts = null
}
JackpotDisplayer_AGD.prototype.XTRegisterCallbacks = function() {
    FOXLink.prototype.XTRegisterCallbacks.call(this);
    XT.RegisterCallbackEvent(Vars.Evt_Internal_BetChanged, this.UpdateJackpotValues, this)
};
JackpotDisplayer_AGD.prototype.HandleInitResponse = function(param) {
    this.ParseJackpotData(param)
};
JackpotDisplayer_AGD.prototype.ParseJackpotData = function(dict) {
    if (dict["gameInfo"] != undefined) {
        var data = dict["gameInfo"].replace("-", "_");
        var gameInfo = JSON5.parse(data);
        if (gameInfo["props"] != undefined) {
            var jpData = gameInfo["props"];
            this.jackpotWinAmounts = [];
            for (var jpIndex = 0; jpIndex < this.orderedJackpotMasks.length; jpIndex++)
                if (jpData[this.orderedJackpotMasks[jpIndex]] != undefined) {
                    var jpValue = jpData[this.orderedJackpotMasks[jpIndex]].toString();
                    this.jackpotWinAmounts.push(_number.otod(jpValue.replace("'",
                        "")))
                } else this.jackpotWinAmounts.push(-1)
        }
    }
};
JackpotDisplayer_AGD.prototype.UpdateJackpotValues = function() {
    // Bet-change can fire before the server init response contains gameInfo.props.
    // Leave the displayed jackpot untouched until valid multipliers are available.
    if (!Array.isArray(this.orderedJackpots) || !Array.isArray(this.jackpotWinAmounts)) return;
    if (typeof CoinManager === "undefined" || !CoinManager || typeof CoinManager.GetNextBet !== "function") return;
    var nextBet = CoinManager.GetNextBet();
    if (typeof nextBet !== "number" || !isFinite(nextBet)) return;
    for (var jpIndex = 0; jpIndex < this.orderedJackpots.length; jpIndex++) {
        var jackpot = this.orderedJackpots[jpIndex];
        var multiplier = this.jackpotWinAmounts[jpIndex];
        if (jackpot && typeof jackpot.SetValueManually === "function" &&
            typeof multiplier === "number" && isFinite(multiplier)) {
            jackpot.SetValueManually(nextBet * multiplier);
        }
    }
};
