var WinLimitVars = {
    WinLimit_TotalBetMultiplier: "WinLimit_TotalBetMultiplier",
    WinLimit_TotalAmount: "WinLimit_TotalAmount",
    WinLimit_UncappedWinLines: "WinLimit_UncappedWinLines"
};
WinLimitFOX.prototype = Object.create(FOXLink.prototype);
WinLimitFOX.prototype.constructor = WinLimitFOX;

function WinLimitFOX() {
    FOXLink.call(this);
    this.defaultWinLimit = "tbm";
    this.winLimitsValues = {};
    this.isCollect = false;
    this.isBonusCollect = false;
    this.isSpin = false;
    this.cycleWin = 0;
    this.prevCycleWin = 0;
    this.cycleWinBeforeRespins = 0;
    this.cycleWinBeforeFreeSpins = 0;
    this.bonusWinsInFreeSpins = 0;
    this.bFreeSpinEndsWithRespin = false;
    this.bRemoveBGTAtBonusRespin = false;
    this.forceBonusCollectOnCapDuringBonus = false
}
WinLimitFOX.prototype.XTRegisterCallbacks = function() {
    FOXLink.prototype.XTRegisterCallbacks.call(this);
    XT.RegisterCallbackEvent(Vars.Evt_Internal_SpinStarted, this.OnSpinStarted, this)
};
WinLimitFOX.prototype.XTInitVariablesAndEvents = function() {
    XT.SetInt(WinLimitVars.WinLimit_TotalBetMultiplier, 0);
    XT.SetDouble(WinLimitVars.WinLimit_TotalAmount, 0);
    XT.SetObject(WinLimitVars.WinLimit_UncappedWinLines, null)
};
WinLimitFOX.prototype.HandleInitResponse = function(dict) {
    var key = "wl_i";
    if (dict[key] == undefined) return;
    var splitTypes = dict[key].split(";");
    if (splitTypes.length == 0) return;
    for (var i = 0; i < splitTypes.length; i++) {
        var split = splitTypes[i].split("~");
        if (split.length < 2) return;
        this.winLimitsValues[split[0]] = _number.otoi(split[1])
    }
    var totalBetMultiplier = this.winLimitsValues[this.defaultWinLimit] != undefined ? this.winLimitsValues[this.defaultWinLimit] : 0;
    XT.SetInt(WinLimitVars.WinLimit_TotalBetMultiplier, totalBetMultiplier);
    this.HandleSpinResponse(dict);
    this.HandleBonusRespinResponse(dict)
};
WinLimitFOX.prototype.HandleSpinResponse = function(dict) {
    if (this.CapValuesIfNeeded(dict)) {
        if (this.isCollect && dict[GameProtocolDictionary.freeSpinCurrentNumber] != undefined) {
            var currentFS = _number.otoi(dict[GameProtocolDictionary.freeSpinCurrentNumber]);
            currentFS--;
            if (currentFS == 0) {
                delete dict[GameProtocolDictionary.freeSpinCurrentNumber];
                delete dict[GameProtocolDictionary.freeSpinMaxNumber];
                delete dict[GameProtocolDictionary.freeSpinTotalNumber]
            } else if (dict[GameProtocolDictionary.freeSpinTotalNumber] == undefined) dict[GameProtocolDictionary.freeSpinTotalNumber] =
                currentFS.toString();
            if (dict[GameProtocolDictionary.mysteryScatterGame] != undefined) delete dict[GameProtocolDictionary.mysteryScatterGame];
            if (this.WeHaveFSChainData(dict)) delete dict[GameProtocolDictionary.freeSpinMaxNumber]
        }
        if (dict["rs_p"] != undefined && dict["rs_t"] == undefined) {
            var respinsPlayed = dict["rs_p"];
            delete dict["rs_p"];
            dict["rs_t"] = respinsPlayed;
            if (this.bRemoveBGTAtBonusRespin) {
                if (dict[GameProtocolDictionary.BonusGame.gameOver] != undefined) dict[GameProtocolDictionary.BonusGame.gameOver] = "1";
                if (respinsPlayed == "0")
                    if (dict["bgt"] != undefined) delete dict["bgt"]
            }
        }
        if (this.bFreeSpinEndsWithRespin)
            if (dict[GameProtocolDictionary.freeSpinCurrentNumber] != undefined) {
                if (dict["rs_t"] == undefined) dict["rs_t"] = "1";
                if (dict["prg"] != undefined) dict["prg"] = "0,0"
            }
        if ((this.isCollect || this.isSpin) && (dict[GameProtocolDictionary.BonusGame.bonusGameExists] != undefined || dict[GameProtocolDictionary.BonusGame.level] != undefined || dict[GameProtocolDictionary.BonusGame.currentBonusRespin] != undefined || dict[GameProtocolDictionary.BonusGame.status] !=
                undefined || dict["wof_status"] != undefined)) {
            delete dict[GameProtocolDictionary.BonusGame.bonusGameExists];
            delete dict[GameProtocolDictionary.BonusGame.level];
            delete dict[GameProtocolDictionary.BonusGame.currentBonusRespin];
            delete dict[GameProtocolDictionary.BonusGame.status];
            delete dict["wof_status"]
        }
    }
};
WinLimitFOX.prototype.HandleBonusRespinResponse = function(dict) {
    var fsr = XT.GetObject(Vars.ReceivedFreeSpinsResponse);
    if (this.CapValuesIfNeeded(dict))
        if (this.isBonusCollect) {
            dict[GameProtocolDictionary.BonusGame.gameOver] = "1";
            if (dict[GameProtocolDictionary.BonusGame.extraRetriggersWon] != undefined) delete dict[GameProtocolDictionary.BonusGame.extraRetriggersWon];
            if (dict[GameProtocolDictionary.BonusGame.currentBonusRespin] != undefined && dict[GameProtocolDictionary.BonusGame.maxBonusRespins] != undefined) dict[GameProtocolDictionary.BonusGame.currentBonusRespin] =
                dict[GameProtocolDictionary.BonusGame.maxBonusRespins];
            if (fsr != null && fsr.IsFreeSpin) fsr.TotalSpins = fsr.CurrentSpin - 1
        } else {
            if (this.isCollect)
                if (fsr != null && fsr.IsFreeSpin) fsr.TotalSpins = fsr.CurrentSpin - 1
        }
    else if (fsr != null && fsr.IsFreeSpin)
        if (dict[GameProtocolDictionary.BonusGame.gameOver] != undefined && dict[GameProtocolDictionary.BonusGame.gameOver] == "1") this.bonusWinsInFreeSpins += GameProtocolCommonParser.ParseDouble(dict, GameProtocolDictionary.BonusGame.realWin)
};
WinLimitFOX.prototype.HandlePickBonusResponse = function(dict) {
    this.prevCycleWin = this.cycleWin;
    var fsr = XT.GetObject(Vars.ReceivedFreeSpinsResponse);
    if (this.CapValuesIfNeeded(dict)) {
        if (this.isCollect)
            if (dict[GameProtocolDictionary.freeSpinCurrentNumber] != undefined) {
                var currentFS = _number.otoi(dict[GameProtocolDictionary.freeSpinCurrentNumber]);
                currentFS--;
                if (dict[GameProtocolDictionary.freeSpinTotalNumber] == undefined) dict[GameProtocolDictionary.freeSpinTotalNumber] = currentFS.toString()
            } else if (fsr.IsFreeSpin) fsr.TotalSpins =
            fsr.CurrentSpin - 1
    } else if (fsr != null && fsr.IsFreeSpin)
        if (dict[GameProtocolDictionary.BonusGame.gameOver] != undefined && dict[GameProtocolDictionary.BonusGame.gameOver] == "1") this.bonusWinsInFreeSpins += GameProtocolCommonParser.ParseDouble(dict, GameProtocolDictionary.BonusGame.realWin)
};
WinLimitFOX.prototype.SwitchTotalBetMultiplier = function(key) {
    if (this.winLimitsValues[key] != undefined) XT.SetInt(WinLimitVars.WinLimit_TotalBetMultiplier, this.winLimitsValues[key])
};
WinLimitFOX.prototype.HandlePickFSOptionResponse = function(dict) {
    this.CapValuesIfNeeded(dict)
};
WinLimitFOX.prototype.CapValuesIfNeeded = function(dict) {
    if (dict[GameProtocolDictionary.spinCycleWin] != undefined) this.cycleWin = _number.otod(dict[GameProtocolDictionary.spinCycleWin]);
    var key = "rs_p";
    if (dict[key] != undefined) {
        var numPlayed = _number.otoi(dict[key]);
        if (numPlayed == 0) this.cycleWinBeforeRespins = this.prevCycleWin
    }
    if (dict[GameProtocolDictionary.freeSpinCurrentWin] != undefined) {
        var fsWin = _number.otod(dict[GameProtocolDictionary.freeSpinCurrentWin]);
        if (fsWin == 0) this.cycleWinBeforeFreeSpins = this.cycleWin
    }
    key =
        "wl_ta";
    if (dict[key] == undefined) {
        XT.SetDouble(WinLimitVars.WinLimit_TotalAmount, 0);
        XT.SetObject(WinLimitVars.WinLimit_UncappedWinLines, null);
        XT.SetBool(Vars.WinLimitReached, false);
        return false
    }
    XT.SetBool(Vars.WinLimitReached, true);
    var limitTotal = _number.otod(dict[key]);
    var limitCurrent = String(limitTotal - this.prevCycleWin);
    var limitRespins = String(limitTotal - this.cycleWinBeforeRespins);
    var limitFreeSpins = limitTotal - this.cycleWinBeforeFreeSpins;
    var limitBonusWin = limitTotal - this.prevCycleWin;
    var forceBonusCollect =
        false;
    if (dict[GameProtocolDictionary.winAmountShort] != undefined) dict[GameProtocolDictionary.winAmountShort] = limitCurrent;
    if (dict[GameProtocolDictionary.TumblingWin] != undefined) dict[GameProtocolDictionary.TumblingWin] = limitRespins;
    if (dict[GameProtocolDictionary.freeSpinTotalWin] != undefined) {
        var fsWinTotal = _number.otod(dict[GameProtocolDictionary.freeSpinTotalWin]);
        if (fsWinTotal > limitFreeSpins) fsWinTotal = limitFreeSpins;
        dict[GameProtocolDictionary.freeSpinTotalWin] = String(fsWinTotal)
    }
    if (dict[GameProtocolDictionary.freeSpinCurrentWin] !=
        undefined) dict[GameProtocolDictionary.freeSpinCurrentWin] = (limitFreeSpins - this.bonusWinsInFreeSpins).toString();
    if (dict[GameProtocolDictionary.freeSpinTotalWinMultiplied] != undefined) {
        var fsResTotal = _number.otod(dict[GameProtocolDictionary.freeSpinTotalWinMultiplied]);
        if (fsResTotal > limitFreeSpins) fsResTotal = limitFreeSpins;
        dict[GameProtocolDictionary.freeSpinTotalWinMultiplied] = String(fsResTotal)
    }
    if (dict[GameProtocolDictionary.BonusGame.realWin] != undefined) {
        var bonusWin = _number.otod(dict[GameProtocolDictionary.BonusGame.realWin]);
        if (bonusWin > limitBonusWin) bonusWin = limitBonusWin;
        dict[GameProtocolDictionary.BonusGame.realWin] = bonusWin.toString();
        if (this.forceBonusCollectOnCapDuringBonus) forceBonusCollect = true
    }
    if (dict["bpw"] != undefined) {
        var bonusWin = _number.otod(dict["bpw"]);
        if (bonusWin > limitBonusWin) bonusWin = limitBonusWin;
        if (this.forceBonusCollectOnCapDuringBonus) {
            forceBonusCollect = true;
            dict["bpw"] = "0";
            dict[GameProtocolDictionary.BonusGame.realWin] = bonusWin.toString()
        } else dict["bpw"] = bonusWin.toString()
    }
    XT.SetDouble(WinLimitVars.WinLimit_TotalAmount,
        limitTotal);
    XT.SetObject(WinLimitVars.WinLimit_UncappedWinLines, VSProtocolParser.ParseWinLines(dict));
    var i = 0;
    while (dict[GameProtocolDictionary.winLines(i)] != undefined) delete dict[GameProtocolDictionary.winLines(i++)];
    var action = "";
    if (dict[GameProtocolDictionary.Actions.action] != undefined) action = dict[GameProtocolDictionary.Actions.action];
    var nextAction = "";
    if (dict[GameProtocolDictionary.NextActions.nextAction] != undefined) nextAction = dict[GameProtocolDictionary.NextActions.nextAction];
    this.isCollect =
        action == GameProtocolDictionary.Actions.doCollect || nextAction == GameProtocolDictionary.NextActions.Collect;
    this.isBonusCollect = action == GameProtocolDictionary.Actions.doCollectBonus || nextAction == GameProtocolDictionary.NextActions.CollectBonus;
    this.isSpin = nextAction == GameProtocolDictionary.NextActions.Spin;
    if (forceBonusCollect) {
        this.isBonusCollect = true;
        this.isCollect = false;
        this.isSpin = false
    }
    if (dict[GameProtocolDictionary.Tumbling] != undefined) delete dict[GameProtocolDictionary.Tumbling];
    return true
};
WinLimitFOX.prototype.OnSpinStarted = function() {
    var respinData = XT.GetObject(Vars.RespinData);
    var isNewCycle = !XT.GetBool(Vars.Logic_IsFreeSpin) && (respinData == null || respinData.IsDone);
    if (isNewCycle) {
        this.prevCycleWin = 0;
        this.bonusWinsInFreeSpins = 0
    } else this.prevCycleWin = this.cycleWin
};
WinLimitFOX.prototype.WeHaveFSChainData = function(dict) {
    return dict[GameProtocolDictionary.FreeSpinsChain.spins] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.multipliers] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.sessionsWonSymbolsCount] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.sessionsWonThisSpin] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.spinsTotal] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.multipliersTotal] != undefined || dict[GameProtocolDictionary.FreeSpinsChain.winsTotal] !=
        undefined || dict[GameProtocolDictionary.FreeSpinsChain.multipliedWinTotal] != undefined
};
goog.require("UHT.XTLink");
goog.require("UHT.VS_LinesDefinitions");
goog.require("UHT.System.Misc.Utils");
WinLineInfo_Casanova.prototype = Object.create(WinLineInfo.prototype);
WinLineInfo_Casanova.prototype.constructor = WinLineInfo_Casanova;

function WinLineInfo_Casanova() {
    WinLineInfo.call(this);
    this.isRightToLeft = false
}
VS_SpinExciter_Casanova.prototype = Object.create(VS_SpinExciter.prototype);
VS_SpinExciter_Casanova.prototype.constructor = VS_SpinExciter_Casanova;

function VS_SpinExciter_Casanova() {
    VS_SpinExciter.call(this);
    this.scatteredSymbols = null;
    this.scatteredSymbolsMinCombo = null;
    this.possibleScatteredSymbolsOnReel = null;
    this.scatteredSymbolsTriggerExcitement = null;
    this.optimizeWaysComputation = false;
    this.forcedFinalSymbolsOnScattersComputation = false;
    this.reelShouldExcite = null;
    this.symbolsShouldPlayExcite = null;
    this.symbolsShouldPlayExciteLose = null;
    this.symbolsShouldPlayWin = null;
    this.initialSymbolList = null;
    this.symbolPresenceOnReel_Ways = []
}
VS_SpinExciter_Casanova.prototype.XTRegisterCallbacks = function() {
    VS_SpinExciter.prototype.XTRegisterCallbacks.call(this)
};
VS_SpinExciter_Casanova.prototype.OnScreenSymbols = function(_initialSymbols) {
    VS_SpinExciter.prototype.OnScreenSymbols.call(this, _initialSymbols)
};
VS_SpinExciter_Casanova.prototype.ResetArrays = function() {
    this.reelShouldExcite = _array.create(this.reelsManager.reels.length, false);
    this.symbolsShouldPlayExcite = [];
    this.symbolsShouldPlayExciteLose = [];
    this.symbolsShouldPlayWin = [];
    for (var i = 0; i < this.reelShouldExcite.length; i++) {
        this.reelShouldExcite[i] = false;
        this.symbolsShouldPlayExcite.push([]);
        this.symbolsShouldPlayExciteLose.push([]);
        this.symbolsShouldPlayWin.push([])
    }
    var symbolsCount = 0;
    for (var j = 0; j < this.symbolList.length; j++) symbolsCount += this.symbolList[j].length
};
VS_SpinExciter_Casanova.prototype.ReelStopsAfter = function(idxToCheck, idxReference) {
    var reelStopOrder = XT.GetObject(Vars.ReelsStopOrder);
    var refPassed = false;
    for (var i = 0; i < reelStopOrder.length; i++) {
        if (idxToCheck == reelStopOrder[i]) break;
        if (idxReference == reelStopOrder[i]) refPassed = true
    }
    return refPassed
};
VS_SpinExciter_Casanova.prototype.CloneWinLineInfo = function(sourceWLI) {
    var clone = new WinLineInfo_Casanova;
    clone.Positions = _array.create(sourceWLI.Positions.length, 0);
    for (var i = 0; i < clone.Positions.length; i++) clone.Positions[i] = sourceWLI.Positions[i];
    clone.Id = sourceWLI.Id;
    clone.dominatingSymbol = sourceWLI.dominatingSymbol;
    clone.isRightToLeft = sourceWLI.isRightToLeft;
    return clone
};
VS_SpinExciter_Casanova.prototype.SimulateStopsOnReel = function(reelIdx) {
    var reels = this.reelsManager.reels.length;
    var i;
    var j;
    var rIndex;
    for (var lineIdx = 0; lineIdx < this.betLines.length; lineIdx++) {
        var wli = this.CloneWinLineInfo(this.betLines[lineIdx]);
        var winningsymbol = 2;
        var forceEndTheLine = false;
        var passedCurrentReel = false;
        for (i = 0; i < wli.Positions.length; i++) {
            if (reelIdx == (wli.isRightToLeft ? wli.Positions.length - 1 - i : i)) {
                passedCurrentReel = true;
                continue
            }
            if (this.ReelStopsAfter(wli.isRightToLeft ? wli.Positions.length -
                    1 - i : i, reelIdx)) forceEndTheLine = true;
            var pos = wli.Positions[i];
            var reelIndex = pos % reels;
            var reelPosIdx = Math.floor(pos / reels);
            var symbol = this.GetSymbolFromReel(reelPosIdx, reelIndex);
            if (symbol != 2 || forceEndTheLine)
                if (forceEndTheLine || symbol != winningsymbol && winningsymbol != 2 || symbol < 2) {
                    var newLength = passedCurrentReel ? i : 0;
                    var newPos = _array.create(newLength, 0);
                    for (j = 0; j < newLength; j++) newPos[j] = wli.Positions[j];
                    wli.Positions = newPos;
                    break
                } else winningsymbol = symbol;
            else this.StillPossibleWinComboWild[i] = true;
            if (!this.betLines[lineIdx].containsWild) this.betLines[lineIdx].containsWild = symbol == 2
        }
        this.betLines[lineIdx].dominatingSymbol = winningsymbol;
        if (winningsymbol > 1)
            if (this.symbolPaying[winningsymbol] <= wli.Positions.length) {
                this.SetReelShouldExcite(reelIdx);
                if (this.hasLoopExciteImportant) this.ExcitedImportantSymbols[reelIdx][winningsymbol] = true;
                if (this.payoutData != null) this.AccumulatedPossibleWin[reelIdx] += this.payoutData[winningsymbol][wli.Positions.length - 1] * XT.GetDouble(Vars.CurrentWinMultiplier);
                var lineIsPaying =
                    false;
                if (this.symbolPaying[winningsymbol] <= (wli.isRightToLeft ? this.betLines[lineIdx].Positions.length - 1 - reelIdx : reelIdx)) lineIsPaying = true;
                for (i = 0; i < wli.Positions.length; i++) {
                    if (reelIdx == (wli.isRightToLeft ? this.betLines[lineIdx].Positions.length - 1 - i : i)) {
                        lineIsPaying = false;
                        continue
                    }
                    if (lineIsPaying) this.symbolsShouldPlayWin[reelIdx].push(wli.Positions[i]);
                    this.symbolsShouldPlayExcite[reelIdx].push(wli.Positions[i])
                }
            }
    }
    if (this.ScatterPays == SpecialSymbolPayType.Everywhere) this.SimulateReelStopForScatteredSymbol(1,
        reelIdx);
    for (i = 0; i < this.scatteredSymbols.length; i++) this.SimulateReelStopForScatteredSymbol(this.scatteredSymbols[i], reelIdx)
};
VS_SpinExciter_Casanova.prototype.SimulateReelStopForScatteredSymbol = function(symbolId, reelIdx) {
    var yetVisible = 0;
    var symbolsOnReels = 0;
    var reelsNotStoppedYet = 0;
    var isRealScatterSymbol = symbolId == 1;
    var lines = XT.GetInt(Vars.Lines);
    this.initialSymbolList = XT.GetObject(Vars.InitialResultScreenSymbols);
    var weHaveInitialSymbols = this.initialSymbolList != null && this.initialSymbolList.length > 0 && !this.forcedFinalSymbolsOnScattersComputation;
    for (var i = 0; i < this.reelsManager.reels.length; i++) {
        if (this.SymbolsPresentAnywhereOnReel(symbolId,
                i) <= 0) continue;
        symbolsOnReels += weHaveInitialSymbols ? this.InitialSymbolAppearencesOnReel(symbolId, i) : this.SymbolAppearencesOnReel(symbolId, i);
        if (i == reelIdx || this.ReelStopsAfter(i, reelIdx)) {
            reelsNotStoppedYet++;
            continue
        }
        yetVisible += this.SymbolAppearencesOnReel(symbolId, i)
    }
    if (isRealScatterSymbol) {
        if (this.ScatterIsStacked) {
            reelsNotStoppedYet = 0;
            for (var i = 0; i < this.reelsManager.reels.length; i++)
                if ((i == reelIdx || this.ReelStopsAfter(i, reelIdx)) && this.SymbolsPresentAnywhereOnReel(symbolId, i) > 0) reelsNotStoppedYet +=
                    this.reelsManager.reels[i].symbolHolders.length
        }
        if (yetVisible + reelsNotStoppedYet >= this.GetScatterMinCombo()) this.StillPossibleWinComboScatter[reelIdx] = true;
        var maxScattersOnNextReel = this.ScatterIsStacked ? this.reelsManager.reels[reelIdx].symbolHolders.length : 1;
        if (this.SymbolsPresentAnywhereOnReel(symbolId, reelIdx) > 0 && yetVisible >= this.GetScatterMinCombo() - maxScattersOnNextReel) {
            this.AccumulatedPossibleWin[reelIdx] += Math.ceil(this.payoutThreshold * (this.optimizeWaysComputation && XT.GetBool(Vars.GameHasWaysInsteadOfLines) ?
                XT.GetInt(Vars.BetToTotalBetMultiplier) : lines));
            this.SetReelShouldExcite(reelIdx)
        }
        if (symbolsOnReels >= this.GetScatterMinCombo())
            for (var j = 0; j < this.ShouldAnimateScatter.length; j++) this.ShouldAnimateScatter[j] = true
    } else {
        var symbolIndex = _array.indexOf(symbolId, this.scatteredSymbols);
        var symbolsOnCurrentReel = weHaveInitialSymbols ? this.InitialSymbolAppearencesOnReel(symbolId, reelIdx) : this.SymbolAppearencesOnReel(symbolId, reelIdx);
        if (yetVisible + symbolsOnCurrentReel + (reelsNotStoppedYet - 1) * this.possibleScatteredSymbolsOnReel[symbolIndex] >=
            this.scatteredSymbolsMinCombo[symbolIndex]) this.StillPossibleWinComboPerSymbol[reelIdx][symbolId] = true;
        if (this.scatteredSymbolsTriggerExcitement[symbolIndex])
            if (this.SymbolsPresentAnywhereOnReel(symbolId, reelIdx) > 0)
                if (yetVisible >= this.scatteredSymbolsMinCombo[symbolIndex] - this.possibleScatteredSymbolsOnReel[symbolIndex]) {
                    this.AccumulatedPossibleWin[reelIdx] += Math.ceil(this.payoutThreshold * (this.optimizeWaysComputation && XT.GetBool(Vars.GameHasWaysInsteadOfLines) ? XT.GetInt(Vars.BetToTotalBetMultiplier) :
                        lines));
                    this.SetReelShouldExcite(reelIdx)
                }
    }
};
VS_SpinExciter_Casanova.prototype.SetReelShouldExcite = function(reelIdx) {
    var reelStopOrder = XT.GetObject(Vars.ReelsStopOrder);
    for (var rIndex = 0; rIndex < reelStopOrder.length; rIndex++)
        if (reelStopOrder[rIndex] == reelIdx) {
            if (rIndex >= this.firstExcitedReel) this.reelShouldExcite[reelIdx] = true;
            break
        }
};
VS_SpinExciter_Casanova.prototype.SimulateStops = function() {
    this.ResetArrays();
    for (var i = 0; i < this.reelsManager.reels.length; i++) this.SimulateStopsOnReel(i)
};
VS_SpinExciter_Casanova.prototype.SimulateStops_Ways = function() {
    this.ResetArrays();
    var i;
    var j;
    if (this.payoutData != null) {
        if (this.symbolPresenceOnReel_Ways.length == 0)
            for (i = 0; i < this.payoutData.length; i++) {
                this.symbolPresenceOnReel_Ways.push([]);
                for (j = 0; j < this.payoutData[i].length; j++) this.symbolPresenceOnReel_Ways[i].push(0)
            } else
                for (i = 0; i < this.symbolPresenceOnReel_Ways.length; i++)
                    for (j = 0; j < this.symbolPresenceOnReel_Ways[i].length; j++) this.symbolPresenceOnReel_Ways[i][j] = 0;
        var symbolID = 0;
        for (i = 0; i <
            this.symbolList.length; i++)
            for (j = 0; j < this.symbolList[i].length; j++) {
                symbolID = this.symbolList[i][j];
                if (this.SymbolIsWild(symbolID)) this.symbolPresenceOnReel_Ways[2][i]++;
                else this.symbolPresenceOnReel_Ways[symbolID][i]++
            }
        for (i = 0; i < this.reelsManager.reels.length; i++) this.SimulateStopsOnReel_Ways(i)
    }
};
VS_SpinExciter_Casanova.prototype.SimulateStopsOnReel_Ways = function(reelIdx) {
    var rightToLeftWay = false;
    var i;
    var j;
    for (var symbolID = 2; symbolID < this.symbolPresenceOnReel_Ways.length; symbolID++) {
        if (!this.HasPayout(symbolID)) continue;
        var forceEndTheLine = false;
        var passedCurrentReel = false;
        var winWaysLength = this.symbolPresenceOnReel_Ways[symbolID].length;
        for (i = 0; i < this.symbolPresenceOnReel_Ways[symbolID].length; i++) {
            var r2lDependentIdx = rightToLeftWay ? this.symbolPresenceOnReel_Ways[symbolID].length - 1 - i : i;
            if (reelIdx == r2lDependentIdx) {
                passedCurrentReel = true;
                continue
            }
            if (this.ReelStopsAfter(r2lDependentIdx, reelIdx)) forceEndTheLine = true;
            if (forceEndTheLine || this.symbolPresenceOnReel_Ways[symbolID][r2lDependentIdx] == 0 && this.symbolPresenceOnReel_Ways[2][r2lDependentIdx] == 0) {
                winWaysLength = passedCurrentReel ? i : 0;
                break
            } else if (this.symbolPresenceOnReel_Ways[2][r2lDependentIdx] > 0) this.StillPossibleWinComboWild[i] = true
        }
        if (this.symbolPaying[symbolID] <= winWaysLength) {
            this.SetReelShouldExcite(reelIdx);
            if (this.hasLoopExciteImportant) this.ExcitedImportantSymbols[reelIdx][symbolID] =
                true;
            var noOfWays = 1;
            for (i = 0; i < winWaysLength; i++) {
                var idx = rightToLeftWay ? this.symbolPresenceOnReel_Ways[symbolID].length - 1 - i : i;
                var presenceOnIdx = this.symbolPresenceOnReel_Ways[symbolID][idx];
                if (idx == reelIdx) presenceOnIdx = this.symbolList[reelIdx].length;
                else if (symbolID != 2) presenceOnIdx += this.symbolPresenceOnReel_Ways[2][idx];
                noOfWays *= presenceOnIdx
            }
            if (this.payoutData != null) this.AccumulatedPossibleWin[reelIdx] += noOfWays * this.payoutData[symbolID][winWaysLength - 1] * XT.GetDouble(Vars.CurrentWinMultiplier);
            var lineIsPaying = false;
            if (this.symbolPaying[symbolID] <= (rightToLeftWay ? this.symbolPresenceOnReel_Ways[symbolID].length - 1 - reelIdx : reelIdx)) lineIsPaying = true;
            for (i = 0; i < winWaysLength; i++) {
                if (reelIdx == (rightToLeftWay ? this.symbolPresenceOnReel_Ways[symbolID].length - 1 - i : i)) {
                    lineIsPaying = false;
                    continue
                }
                if (lineIsPaying)
                    for (j = 0; j < this.symbolList[i].length; j++)
                        if (this.symbolList[i][j] == symbolID || this.symbolList[i][j] == 2) this.symbolsShouldPlayWin[reelIdx].push(j * this.symbolList.length + i);
                for (j = 0; j < this.symbolList[i].length; j++)
                    if (this.symbolList[i][j] ==
                        symbolID || this.symbolList[i][j] == 2) {
                        if (lineIsPaying) this.symbolsShouldPlayWin[reelIdx].push(j * this.symbolList.length + i);
                        this.symbolsShouldPlayExcite[reelIdx].push(j * this.symbolList.length + i)
                    }
            }
        }
        if (XT.GetBool(Vars.LinesPaysBothWays)) {
            rightToLeftWay = !rightToLeftWay;
            if (rightToLeftWay) symbolID--
        }
    }
    if (this.ScatterPays == SpecialSymbolPayType.Everywhere) this.SimulateReelStopForScatteredSymbol(1, reelIdx);
    for (i = 0; i < this.scatteredSymbols.length; i++) this.SimulateReelStopForScatteredSymbol(this.scatteredSymbols[i],
        reelIdx)
};
VS_SpinExciter_Casanova.prototype.HasPayout = function(symbolID) {
    for (var i = 0; i < this.payoutData[symbolID].length; i++)
        if (this.payoutData[symbolID][i] > 0) return true;
    return false
};
VS_SpinExciter_Casanova.prototype.UpdateBetLines = function() {
    var lines = XT.GetInt(Vars.Lines);
    var reels = this.symbolList.length;
    var linesPaysBothWays = XT.GetBool(Vars.LinesPaysBothWays);
    this.betLines = _array.create(linesPaysBothWays ? lines * 2 : lines, null);
    for (var i = 0; i < this.betLines.length; i++) {
        var isRightToLeft = i >= lines;
        this.betLines[i] = new WinLineInfo_Casanova;
        this.betLines[i].Id = i + 1;
        this.betLines[i].Positions = _array.create(reels, 0);
        this.betLines[i].containsWild = false;
        this.betLines[i].isRightToLeft = isRightToLeft;
        for (var j = 0; j < reels; j++)
            if (isRightToLeft) this.betLines[i].Positions[j] = this.linesDef.lines[i - lines].symbolIndices[reels - 1 - j];
            else this.betLines[i].Positions[j] = this.linesDef.lines[i].symbolIndices[j]
    }
};
VS_SpinExciter_Casanova.prototype.ComputePossibleWins = function() {
    if (this.optimizeWaysComputation && XT.GetBool(Vars.GameHasWaysInsteadOfLines)) this.SimulateStops_Ways();
    else {
        this.UpdateBetLines();
        this.SimulateStops()
    }
    this.UpdateActualWinCombo();
    this.SetWinComboSounds()
};
VS_SpinExciter_Casanova.prototype.Excite = function(reelToStop) {
    if (!XT.GetObject(Vars.ReelsCanBeExcited)[reelToStop]) return false;
    var enoughMoney = false;
    if (this.payoutData == null) enoughMoney = true;
    else {
        var lines = XT.GetInt(Vars.Lines);
        if (this.AccumulatedPossibleWin[reelToStop] >= this.payoutThreshold * (this.optimizeWaysComputation && XT.GetBool(Vars.GameHasWaysInsteadOfLines) ? XT.GetInt(Vars.BetToTotalBetMultiplier) : lines)) enoughMoney = true
    }
    return this.reelShouldExcite[reelToStop] && enoughMoney
};
VS_SpinExciter_Casanova.prototype.UpdateSymbol = function(rsh, reelIdx, allowScatterExcite) {
    var symbolId = rsh.currentSymbol.symbolId;
    var scatterIsWild = XT.GetBool(Vars.ScatterSymbolIsWild);
    if (!this.CanHighlightOff(symbolId) && !(scatterIsWild && symbolId == 1)) return;
    var orderedIdx = rsh.GetOrderedSymbolIdx();
    var foundExcited = false;
    var foundWinning = false;
    var i;
    for (i = 0; i < this.symbolsShouldPlayExcite[reelIdx].length; i++)
        if (orderedIdx == this.symbolsShouldPlayExcite[reelIdx][i]) foundExcited = true;
    for (i = 0; i < this.symbolsShouldPlayWin[reelIdx].length; i++)
        if (orderedIdx ==
            this.symbolsShouldPlayWin[reelIdx][i]) foundWinning = true;
    if (foundWinning && foundExcited) rsh.currentSymbol.SetWinExcited();
    else if (foundWinning) rsh.currentSymbol.SetWinning();
    else if (foundExcited) rsh.currentSymbol.SetExcited();
    else if (!this.CanHighlightOff(symbolId) && (scatterIsWild && symbolId == 1)) rsh.currentSymbol.SetNormal();
    else rsh.currentSymbol.SetHighlightOff()
};
VS_SpinExciter_Casanova.prototype.ReelStopped = function(reelIdx, isStoppingFast) {
    if (isStoppingFast) return;
    var reelStopOrder = XT.GetObject(Vars.ReelsStopOrder);
    var i = 0;
    for (i = 0; i < reelStopOrder.length; i++)
        if (reelIdx == reelStopOrder[i])
            if (i < this.firstExcitedReel - 1) return;
    var atLeastOneExcitedReel = false;
    var nextReelIdx = 0;
    var nextReelIdxInOrder = 0;
    for (i = 0; i < reelStopOrder.length; i++)
        if (reelIdx == reelStopOrder[i]) {
            if (i == reelStopOrder.length - 1) nextReelIdxInOrder = i;
            else nextReelIdxInOrder = i + 1;
            nextReelIdx = reelStopOrder[nextReelIdxInOrder]
        }
    for (i =
        0; i <= nextReelIdxInOrder; i++)
        if (this.Excite(reelStopOrder[i])) atLeastOneExcitedReel = true;
    if (atLeastOneExcitedReel)
        for (i = 0; i < reelStopOrder.length; i++) {
            var reel = this.reelsManager.reels[reelStopOrder[i]];
            for (var j = 0; j < reel.symbolHolders.length; j++) this.UpdateSymbol(reel.symbolHolders[j], nextReelIdx, false);
            if (reelStopOrder[i] == reelIdx) break
        }
};
VS_SpinExciter_Casanova.prototype.InitialSymbolAppearencesOnReel = function(symbolId, reelidx) {
    var ret = 0;
    for (var i = 0; i < this.initialSymbolList[reelidx].length; i++)
        if (this.initialSymbolList[reelidx][i] == symbolId) ret++;
    return ret
};
VS_SpinExciter_Casanova.prototype.UpdateActualWinCombo = function() {
    var winLines = XT.GetObject(Vars.ReceivedWinLines);
    if (winLines == null || winLines.length == 0) return;
    var longestWLine = winLines[0];
    var i;
    for (i = 0; i < winLines.length; i++)
        if (longestWLine.WinPositions.length < winLines[i].WinPositions.length) longestWLine = winLines[i];
    var winPos = longestWLine.WinPositions;
    for (i = 0; i < winPos.length; i++) this.ActualWinCombo[winPos[i] % this.reelsManager.reels.length] = true
};
