SymbolPanelSorter.prototype = Object.create(Component.prototype);
SymbolPanelSorter.prototype.constructor = SymbolPanelSorter;

function SymbolPanelSorter() {
    Component.call(this);
    this.startingDepth = 0;
    this.orderedPanels = null;
    this.sortingDepth = 0
}
SymbolPanelSorter.prototype.UpdateDepth = function(depthOffset) {
    this.sortingDepth = this.startingDepth + depthOffset;
    for (var pIndex = 0; pIndex < this.orderedPanels.length; pIndex++) this.orderedPanels[pIndex].depth = this.sortingDepth + pIndex
};
SymbolPanelSorter.prototype.SetAlpha = function(_alpha) {
    for (var pIndex = 0; pIndex < this.orderedPanels.length; pIndex++) this.orderedPanels[pIndex].alpha = _alpha
};
goog.require("UHT.Engine");
SymbolSorterManager.prototype = Object.create(XTLink.prototype);
SymbolSorterManager.prototype.constructor = SymbolSorterManager;

function SymbolSorterManager() {
    XTLink.call(this);
    this.sortOrder = SymbolSorterManager.SortOrder.topLeft;
    this.symbolHoldersOffset = 1;
    this.reelHolderOffset = 1;
    this.rm = null;
    this.vs = null;
    this.sps = null;
    this.newDepth = 0
}
SymbolSorterManager.SortOrder = {
    topLeft: 0,
    topRight: 1,
    bottomLeft: 2,
    bottomRight: 3
};
SymbolSorterManager.prototype.XTRegisterCallbacks = function() {
    XT.RegisterCallbackEvent(Vars.Evt_Internal_GameInit, this.OnGameInit, this);
    XT.RegisterCallbackEvent(Vars.Evt_Internal_UpdateSymbolsDepth, this.SortSymbols, this)
};
SymbolSorterManager.prototype.OnDestroy = function() {
    XT.UnregisterCallbackEvent(this.OnGameInit, this);
    XT.UnregisterCallbackEvent(this.SortSymbols, this)
};
SymbolSorterManager.prototype.OnGameInit = function() {
    this.rm = XT.GetObject(Vars.ReelsManagerObject);
    this.SortSymbols()
};
SymbolSorterManager.prototype.SortSymbols = function() {
    if (this.rm != null)
        for (var rIndex = 0; rIndex < this.rm.reels.length; rIndex++) {
            var symbolIndex = 0;
            for (var sIndex = 0; sIndex < this.rm.reels[rIndex].sortedSymbolHolders.length; sIndex++) {
                this.vs = this.rm.reels[rIndex].sortedSymbolHolders[sIndex].currentSymbol;
                if (this.vs != null) {
                    this.sps = this.vs.GetComponent(SymbolPanelSorter);
                    if (this.sps != null) {
                        switch (this.sortOrder) {
                            case SymbolSorterManager.SortOrder.topLeft:
                                this.newDepth = rIndex * this.reelHolderOffset + symbolIndex *
                                    this.symbolHoldersOffset;
                                break;
                            case SymbolSorterManager.SortOrder.topRight:
                                this.newDepth = (this.rm.reels.length - rIndex - 1) * this.reelHolderOffset + symbolIndex * this.symbolHoldersOffset;
                                break;
                            case SymbolSorterManager.SortOrder.bottomLeft:
                                this.newDepth = rIndex * this.reelHolderOffset + (this.rm.reels[rIndex].sortedSymbolHolders.length - symbolIndex - 1) * this.symbolHoldersOffset;
                                break;
                            case SymbolSorterManager.SortOrder.bottomRight:
                                this.newDepth = (this.rm.reels.length - rIndex - 1) * this.reelHolderOffset + (this.rm.reels[rIndex].sortedSymbolHolders.length -
                                    symbolIndex - 1) * this.symbolHoldersOffset;
                                break;
                            default:
                                this.newDepth = 0;
                                break
                        }
                        this.sps.UpdateDepth(this.newDepth)
                    }
                    symbolIndex++
                }
            }
        }
};
goog.require("UHT.Engine");
SymbolsFader.prototype = Object.create(XTLink.prototype);
SymbolsFader.prototype.constructor = SymbolsFader;

function SymbolsFader() {
    XTLink.call(this);
    this.alphaValue = 1;
    this.includeLoopers = false;
    this.symbolPositions = [];
    this.oldAlphaValue = 1;
    this.rm = null;
    this.isAllowed = true
}
SymbolsFader.prototype.XTRegisterCallbacks = function() {
    XT.RegisterCallbackEvent(Vars.Evt_Internal_SpinStarted, this.OnSpinStarted, this);
    XT.RegisterCallbackEvent(Vars.Evt_Internal_SpinEnded, this.OnSpinEnded, this)
};
SymbolsFader.prototype.OnSpinStarted = function() {
    this.alphaValue = 1;
    this.Update();
    this.isAllowed = false
};
SymbolsFader.prototype.OnSpinEnded = function() {
    this.isAllowed = true
};
SymbolsFader.prototype.Start = function() {
    this.oldAlphaValue = this.alphaValue
};
SymbolsFader.prototype.Update = function() {
    if (this.rm == null) this.rm = XT.GetObject(Vars.ReelsManagerObject);
    if (Math.abs(this.alphaValue - this.oldAlphaValue) > .001) {
        this.oldAlphaValue = this.alphaValue;
        for (var i = 0; i < this.rm.reels.length; i++) {
            if (this.includeLoopers)
                for (var j = 0; j < this.rm.reels[i].symbolLoopHolders.length; j++)
                    if (this.rm.reels[i].symbolLoopHolders[j].currentSymbol != null) this.rm.reels[i].symbolLoopHolders[j].currentSymbol.GetComponent(UIPanel).alpha = this.alphaValue;
            if (this.isAllowed)
                for (var j =
                        0; j < this.rm.reels[i].symbolHolders.length; j++) {
                    var contained = false;
                    var containedIndex = j * this.rm.reels.length + i;
                    for (var index = 0; index < this.symbolPositions.length; index++)
                        if (this.symbolPositions[index] == containedIndex) {
                            contained = true;
                            break
                        }
                    if (contained || this.symbolPositions.length == 0) this.rm.reels[i].symbolHolders[j].currentSymbol.gameObject.GetComponent(UIPanel).alpha = this.alphaValue
                }
        }
    }
};
