goog.require("UHT.Engine");
goog.require("UHT.FOXLink");
BonusGameSelector_AGD.prototype = Object.create(FOXLink.prototype);
BonusGameSelector_AGD.prototype.constructor = BonusGameSelector_AGD;

function BonusGameSelector_AGD() {
    FOXLink.call(this);
    this.showBonus = null;
    this.resumeBonus = null;
    this.closeBonus = null;
    this.bonusData = null;
    this.pickedIndex = 0;
    this.bonusWonIndex = 0
}
BonusGameSelector_AGD.prototype.HandleInitBonusResponse = function(param) {
    this.UpdateBonusWon(param)
};
BonusGameSelector_AGD.prototype.HandlePickBonusResponse = function(param) {
    this.UpdateBonusWon(param);
    if (this.bonusData.GameOver) this.OnBonusClose()
};
BonusGameSelector_AGD.prototype.UpdateBonusWon = function(param) {
    this.pickedIndex = -1;
    this.bonusWonIndex = 0;
    if (param["status"] != undefined) {
        var statuses = param["status"].split(",");
        for (var i = 0; i < statuses.length; i++)
            if (statuses[i] == "1") {
                this.pickedIndex = i;
                break
            }
    }
    if (this.pickedIndex >= 0 && param["wins_mask"] != undefined) {
        var masks = param["wins_mask"].split(",");
        switch (masks[this.pickedIndex]) {
            case "mult":
                this.bonusWonIndex = 0;
                break;
            case "prize":
                this.bonusWonIndex = 1;
                break;
            default:
                this.bonusWonIndex = 0;
                break
        }
    }
};
BonusGameSelector_AGD.prototype.XTRegisterCallbacks = function() {
    FOXLink.prototype.XTRegisterCallbacks.call(this);
    XT.RegisterCallbackEvent(BGVars.Evt_CodeToData_BonusResultWindowShow, this.OnBonusShow, this)
};
BonusGameSelector_AGD.prototype.OnBonusShow = function() {
    this.bonusData = XT.GetObject(Vars.BonusData);
    if (this.bonusData.GameOver) this.resumeBonus.Start();
    else this.showBonus.Start()
};
BonusGameSelector_AGD.prototype.OnBonusClose = function() {
    this.closeBonus[this.bonusWonIndex].Start()
};
BonusGameSelector_AGD.prototype.SendPick = function() {
    XT.SetInt(Vars.BonusPickItemIndex, 0);
    XT.TriggerEvent(BGVars.Evt_ToServer_BonusPickedItem)
};
goog.require("UHT.Engine");
BonusGameWheel_AGD.prototype = Object.create(XTLink.prototype);
BonusGameWheel_AGD.prototype.constructor = BonusGameWheel_AGD;

function BonusGameWheel_AGD() {
    XTLink.call(this);
    this.showBonusWheel = null;
    this.resumeBonusWheel = null;
    this.hideBonusWheel = null;
    this.wheelSpinningPivot = null;
    this.orderedWinValues = null;
    this.startSpinning = null;
    this.stopSpinningCATs = null;
    this.stoppedSpinning = null;
    this.animationController = null;
    this.startAnimationClip = null;
    this.loopingAnimationClip = null;
    this.stopAnimationClips = null;
    this.wheelState = BonusGameWheel_AGD.WheelState.Idle;
    this.currentAnimState = null;
    this.internalAnimationTimer = 0;
    this.bonusData = null;
    this.canStop = false
}
BonusGameWheel_AGD.prototype.XTRegisterCallbacks = function() {
    XT.RegisterCallbackEvent(Vars.Evt_FromServer_BonusInitDone, this.OnBonusInitDone, this);
    XT.RegisterCallbackEvent(Vars.Evt_FromServer_BonusResponseReceived, this.OnBonusResponseReceived, this);
    XT.RegisterCallbackEvent(BGVars.Evt_CodeToData_BonusResultWindowShow, this.OnBonusShow, this);
    XT.RegisterCallbackEvent(BGVars.Evt_CodeToData_BonusResultWindowClose, this.OnBonusHide, this)
};
BonusGameWheel_AGD.prototype.OnBonusShow = function() {
    if (this.bonusData.Level > 0 || this.bonusData.GameOver) {
        XT.SetBool(Vars.Evt_Internal_ResultDisplayer_SkipNextLoopOccasion, true);
        this.wheelSpinningPivot.localRotation(UHTMath.Quaternion.euler(new UHTMath.Vector3(0, 0, 360 / this.orderedWinValues.length * this.GetWinValueIndex())));
        this.resumeBonusWheel.Start()
    } else {
        this.wheelSpinningPivot.localRotation(UHTMath.Quaternion.euler(new UHTMath.Vector3(0, 0, 0)));
        this.showBonusWheel.Start()
    }
};
BonusGameWheel_AGD.prototype.OnBonusHide = function() {
    this.hideBonusWheel.Start()
};
BonusGameWheel_AGD.prototype.OnBonusInitDone = function() {
    this.bonusData = XT.GetObject(Vars.BonusData)
};
BonusGameWheel_AGD.prototype.OnBonusResponseReceived = function() {
    this.canStop = true
};
BonusGameWheel_AGD.prototype.StartSpinning = function(pickIndex) {
    XT.SetInt(BGVars.BonusPickItemIndex, pickIndex);
    XT.TriggerEvent(BGVars.Evt_ToServer_BonusPickedItem);
    this.wheelState = BonusGameWheel_AGD.WheelState.Starting;
    this.canStop = false;
    this.PlayAnimation(this.startAnimationClip, 0);
    this.startSpinning.Start()
};
BonusGameWheel_AGD.prototype.StartLooping = function() {
    this.wheelState = BonusGameWheel_AGD.WheelState.Spinning;
    this.PlayAnimation(this.loopingAnimationClip, this.internalAnimationTimer - this.currentAnimState.length)
};
BonusGameWheel_AGD.prototype.StopSpinning = function() {
    this.wheelState = BonusGameWheel_AGD.WheelState.Stopping;
    this.wheelSpinningPivot.localRotation(UHTMath.Quaternion.euler(new UHTMath.Vector3(0, 0, 360 / this.orderedWinValues.length * this.GetWinValueIndex())));
    var randomStopIndex = Random.Range(0, this.stopAnimationClips.length);
    this.PlayAnimation(this.stopAnimationClips[randomStopIndex], this.internalAnimationTimer - this.currentAnimState.length);
    this.stopSpinningCATs[randomStopIndex].Start()
};
BonusGameWheel_AGD.prototype.StoppedSpinning = function() {
    this.wheelState = BonusGameWheel_AGD.WheelState.Idle;
    this.stoppedSpinning.Start()
};
BonusGameWheel_AGD.prototype.GetWinValueIndex = function() {
    var _winValue = 0;
    for (var i = 0; i < this.bonusData.WheelOfFortune.itemsStatus.length; i++)
        if (this.bonusData.WheelOfFortune.itemsStatus[i] == 1) {
            _winValue = this.bonusData.WheelOfFortune.items[i].amount;
            break
        }
    for (var index = 0; index < this.orderedWinValues.length; index++)
        if (_winValue == this.orderedWinValues[index]) return index;
    return -1
};
BonusGameWheel_AGD.prototype.PlayAnimation = function(clip, timeOffset) {
    this.currentAnimState = this.animationController.GetAnimationState(clip.name);
    this.currentAnimState.enabled = true;
    this.currentAnimState.time = timeOffset;
    this.animationController.clip = clip;
    this.animationController.Sample();
    this.animationController.Play();
    this.internalAnimationTimer = timeOffset
};
BonusGameWheel_AGD.prototype.Update = function() {
    if (this.wheelState == BonusGameWheel_AGD.WheelState.Idle) return;
    this.internalAnimationTimer += Time.deltaTime;
    if (this.internalAnimationTimer > this.currentAnimState.length) switch (this.wheelState) {
        case BonusGameWheel_AGD.WheelState.Starting:
            this.StartLooping();
            break;
        case BonusGameWheel_AGD.WheelState.Spinning:
            if (this.canStop) this.StopSpinning();
            else this.StartLooping();
            break;
        case BonusGameWheel_AGD.WheelState.Stopping:
            this.StoppedSpinning();
            break
    }
};
BonusGameWheel_AGD.WheelState = {
    Starting: 0,
    Spinning: 1,
    Stopping: 2,
    Idle: 3
};
