    XT.RegisterCallbackEvent(Vars.Evt_Internal_FreeSpinsEnded, this.OnSoundLogicStartFreeSpins, this);
    XT.RegisterCallbackEvent(Vars.Evt_Internal_StartVSLogicSounds, this.OnVSLogicStartSounds, this);
